<script lang="ts">import { avatarImageClassName } from '@fex-design/styles/avatar';import { cn } from '@fex/utils';import { getContext } from 'svelte';import type { HTMLImgAttributes } from 'svelte/elements';import { avatarContextKey,type AvatarContext } from './context';interface Props extends Omit<HTMLImgAttributes,'class'>{class?:string}let{class:className,src,...rest}:Props=$props();const {controller,status}=getContext<AvatarContext>(avatarContextKey);$effect(()=>src?controller.load({src:String(src)}):controller.reset())</script>
{#if $status === 'loaded'}<img {...rest} {src} data-slot="avatar-image" class={cn(avatarImageClassName,className)}/>{/if}
